var FACTS=[[
'Banknotes are issued by the Reserve Bank of India (RBI). The ₹1 note is different: the Government of India issues it. Coins are made by the Government of India and the RBI puts them into circulation.',
'Four mints make coins: Mumbai (diamond under the year), Hyderabad (star), Noida (solid dot) and Kolkata (no mark).',
'Every note shows Mahatma Gandhi, the Ashoka Pillar emblem and the value in numbers. The back shows a place or achievement of India.',
'₹2000 notes: the RBI announced in May 2023 that it would stop issuing them, but they are still legal tender. Old ₹500 and ₹1,000 notes were demonetised on 8 November 2016.',
'Coins of 50 paise, ₹1, ₹2, ₹5, ₹10 and ₹20 are legal tender, even in older designs. Coins of 25 paise and below stopped being legal tender on 30 June 2011.',
'A coin of ₹1 or more can pay up to ₹1,000 in one payment; a 50 paise coin up to ₹10. Bank branches may not refuse small notes or coins.',
'Spot a real note: feel the raised print, hold it to light to see the watermark, the thread and the see-through register. Higher notes also have colour-shifting ink and raised lines for blind readers.',
'Torn or dirty notes can be exchanged at bank branches under RBI rules. Never accept a note that feels or looks wrong; ask an adult.'],[
'बैंक नोट भारतीय रिज़र्व बैंक (RBI) जारी करता है। ₹1 का नोट अलग है: उसे भारत सरकार जारी करती है। सिक्के भारत सरकार बनाती है और RBI उन्हें चलन में लाता है।',
'चार टकसालें सिक्के बनाती हैं: मुंबई (साल के नीचे हीरा), हैदराबाद (तारा), नोएडा (ठोस बिंदु) और कोलकाता (कोई निशान नहीं)।',
'हर नोट पर महात्मा गांधी, अशोक स्तंभ का चिह्न और मूल्य अंकों में होता है। पीछे भारत की कोई जगह या उपलब्धि दिखती है।',
'₹2000 के नोट: RBI ने मई 2023 में इन्हें जारी करना बंद करने की घोषणा की, पर ये अब भी वैध मुद्रा हैं। पुराने ₹500 और ₹1,000 के नोट 8 नवंबर 2016 को बंद हुए थे।',
'50 पैसे, ₹1, ₹2, ₹5, ₹10 और ₹20 के सिक्के वैध मुद्रा हैं, पुराने डिज़ाइन के भी। 25 पैसे और उससे छोटे सिक्के 30 जून 2011 से वैध मुद्रा नहीं रहे।',
'₹1 या उससे ऊपर का सिक्का एक भुगतान में ₹1,000 तक चुका सकता है; 50 पैसे का सिक्का ₹10 तक। बैंक शाखाएँ छोटे नोट या सिक्के लेने से मना नहीं कर सकतीं।',
'असली नोट पहचानें: उभरी छपाई छूकर देखें, रोशनी में वॉटरमार्क, धागा और सी-थ्रू रजिस्टर देखें। बड़े नोटों में रंग बदलने वाली स्याही और दृष्टिहीनों के लिए उभरी रेखाएँ भी होती हैं।',
'फटे या गंदे नोट RBI के नियमों के तहत बैंक शाखाओं में बदले जा सकते हैं। जो नोट अजीब लगे उसे न लें; किसी बड़े से पूछें।']];
function refH(){var h=LANG==='hi',i=h?1:0,s='<div class="pp"><h2>'+(h?'भारत के बैंक नोट':'Banknotes of India')+'</h2><p>'+(h?'आज चलन में ये नोट मिलते हैं। हर नोट का अलग रंग और पीछे अलग विरासत-चित्र है।':'These are the notes you can meet today. Each has its own colour and a different heritage picture on the back.')+'</p><div class="rg">';
 NOTES.forEach(function(n){s+='<div class="rc"><div class="nt" style="background:'+n[1]+'"><b>₹'+n[0]+'</b><span>'+n[4]+'</span></div><strong>₹'+n[0]+' · '+n[2][i]+'</strong><small>'+(h?'पीछे: ':'Back: ')+n[3][i]+'</small></div>'});
 s+='</div><p class="sm2">'+(h?'₹1 का नोट भी वैध है और भारत सरकार जारी करती है; यह अब कम दिखता है।':'The ₹1 note is also legal tender, issued by the Government of India, but you will rarely see one now.')+'</p></div><div class="pp"><h2>'+(h?'भारत के सिक्के':'Coins of India')+'</h2><div class="rg">';
 COINS.forEach(function(c){var cp=c[3]?'clip-path:polygon('+Array.from({length:c[3]},function(_,k){var a=k*2*Math.PI/c[3];return(50+50*Math.cos(a)).toFixed(1)+'% '+(50+50*Math.sin(a)).toFixed(1)+'%'}).join(',')+')':'';
  s+='<div class="rc c"><div class="cn" style="background:'+c[1]+';'+cp+'">'+c[0]+'</div><small>'+c[2][i]+'</small></div>'});
 s+='</div></div><div class="pp"><h2>'+(h?'जानने लायक बातें':'Good to know')+'</h2><ul>'+FACTS[i].map(function(x){return'<li>'+x+'</li>'}).join('')+'</ul></div>';return s}
