var KH={"a1": ["आय वह सारा पैसा है जो आता है। ख़र्च वह सारा पैसा है जो जाता है।", "आय में से ख़र्च घटाने पर जो बचता है वह अधिशेष (बचत) है। नकारात्मक अंतर का मतलब है कि आप अपने भविष्य से उधार ले रहे हैं।", "अपने बारे में राय बनाने से पहले 30 दिन हिसाब रखें: लोग अक्सर छोटे ख़र्च ही भूल जाते हैं।", "UPI, वॉलेट और नक़द, सभी ख़र्च गिने जाते हैं। आपके UPI ऐप का इतिहास उन्हें दिखाता है।"], "a2": ["स्थिर ख़र्च हर बार उतने ही रहते हैं: फ़ीस, प्लान, सदस्यताएँ, किराया।", "बदलने वाले ख़र्च हर महीने बदलते हैं: नाश्ता, घूमना-फिरना, गेम, ईंधन।", "पहले स्थिर ख़र्च तय करें। बदलने वाले हिस्से पर आपका नियंत्रण होता है।", "अपने-आप नवीनीकृत होने वाली सदस्यताएँ ऐसे स्थिर ख़र्च हैं जिन्हें लोग भूल जाते हैं। हर कुछ महीनों में उनकी समीक्षा करें।"], "a3": ["दाम वह है जो आप आज चुकाते हैं। मूल्य वह है जो आपको उसे इस्तेमाल करने के पूरे समय में मिलता है।", "महीने या उपयोग के हिसाब से लागत = दाम ÷ महीने या उपयोग की संख्या।", "बड़ी ख़रीदारी से पहले रिव्यू, वारंटी और दोबारा बेचने का मूल्य देखें।", "उलटी गिनती वाले टाइमर और “सिर्फ़ 2 बचे हैं” वाले बैनर जल्दबाज़ी पैदा करते हैं। एक रात सोचकर फ़ैसला करें।"], "a4": ["अपनी आय का 50% ज़रूरतों, 30% चाहतों और 20% बचत के लिए रखकर देखें।", "इसे अपने जीवन के हिसाब से बदलें। ज़रूरतें कम हों तो बचत की गुंजाइश बढ़ती है।", "बचत पहले करें: पैसा आते ही उसे अलग खाते में डाल दें।", "आय बदलने पर हर कुछ महीनों में बँटवारे की समीक्षा करें।"], "a5": ["हर चुनाव में अगला सबसे अच्छा विकल्प छूट जाता है। वही उसकी अवसर लागत है।", "यह सिर्फ़ पैसे की बात नहीं है। आपके समय और ध्यान की भी अवसर लागत होती है।", "पूछें: इस पैसे या समय से और क्या हो सकता था?", "छोटे चुनाव बार-बार दोहराए जाते हैं। रोज़ ₹100 की आदत महीने में ₹3,000 हो जाती है।"], "a6": ["आपातकालीन निधि वह पैसा है जो सिर्फ़ अचानक आई ज़रूरतों के लिए रखा जाता है।", "इसे आसानी से निकाले जा सकने वाले बचत खाते में, ख़र्च के पैसों से अलग रखें।", "इस्तेमाल करें, फिर दोबारा भरें। वयस्क 3 से 6 महीने के ख़र्च जितनी निधि का लक्ष्य रखते हैं।", "निधि होने पर कुछ टूट-फूट जाए तो उधार लेने की ज़रूरत नहीं पड़ती।"], "a7": ["साधारण ब्याज = मूलधन × दर × वर्ष ÷ 100।", "चक्रवृद्धि ब्याज में ब्याज पर भी ब्याज मिलता है, इसलिए बढ़त तेज़ होती जाती है।", "समय की अहमियत दिखने से ज़्यादा है। जल्दी शुरू करें।", "72 का नियम: पैसा दोगुना होने के साल ≈ 72 ÷ सालाना दर।"], "a8": ["महँगाई का मतलब है समय के साथ दामों का आम तौर पर बढ़ना।", "RBI इसे 4% के आसपास रखना चाहता है, दोनों ओर 2% की सीमा के भीतर।", "असल रिटर्न लगभग ब्याज घटा महँगाई होता है।", "बेकार पड़ा नक़द ख़रीदने की ताक़त खोता है, इसलिए लंबे लक्ष्यों के लिए बचत के साथ बढ़ने वाली संपत्तियाँ भी चाहिए।"], "a9": ["UPI आपके बैंक खाते को ऐप से जोड़ता है। पिन सिर्फ़ पैसे भेजने के लिए चाहिए, पाने के लिए कभी नहीं।", "UPI Lite छोटे भुगतान बिना पिन के करता है। UPI Circle में कोई भरोसेमंद परिवारजन आपकी तय की सीमा में आपके खाते से भुगतान कर सकता है।", "डेबिट और प्रीपेड कार्ड आपका बैलेंस ख़र्च करते हैं। ऑनलाइन भुगतान में ऐप के नियंत्रण और टोकनयुक्त कार्ड इस्तेमाल करें।", "डिजिटल रुपया (e₹) RBI का पायलट डिजिटल नक़द है। क्रिप्टो संपत्तियाँ अलग हैं और क़ानूनी मुद्रा नहीं हैं।", "धोखा हो गया? तुरंत 1930 पर फ़ोन करें और cybercrime.gov.in पर शिकायत करें।"], "a10": ["EMI हर महीने की तय किस्त है जिसमें लोन और उसका ब्याज दोनों शामिल हैं।", "कुल चुकाया = EMI × महीनों की संख्या। अतिरिक्त लागत = कुल − दाम।", "लंबी अवधि से EMI घटती है पर कुल लागत बढ़ती है।", "मुख्य तथ्य विवरण (Key Fact Statement) माँगें। कुल EMI आय के लगभग 40% से कम रखें।"], "a11": ["डेबिट आपका बैलेंस इस्तेमाल करता है। क्रेडिट उधार लिया हुआ पैसा है।", "पूरा बिल देय तिथि तक चुकाएँ। सिर्फ़ न्यूनतम राशि चुकाने पर बचे बैलेंस पर ब्याज लगता रहता है।", "कार्ड का उपयोग सीमा के लगभग 30% से कम रखें। इससे आपका क्रेडिट स्कोर बनता है।", "नेटवर्क (RuPay, Visa, Mastercard) तय करता है कि कार्ड कहाँ चलेगा। कार्ड बैंक जारी करता है और शर्तें तय करता है।"], "a12": ["ज़्यादा संभावित रिटर्न के साथ नुक़सान का जोखिम भी ज़्यादा होता है।", "FD और बचत में जोखिम कम और रिटर्न कम होता है। शेयर और इक्विटी फ़ंड ऊपर-नीचे होते हैं पर लंबे समय में ज़्यादा बढ़ सकते हैं।", "पैसे को अलग-अलग संपत्तियों में बाँटें: इसे विविधीकरण कहते हैं।", "“गारंटीड” ऊँचे रिटर्न ख़तरे की घंटी हैं। किसी पर भरोसा करने से पहले SEBI पंजीकरण जाँचें।"]};
