var NEW6=[{"id": "c1", "l": 0, "n": ["Counting money and change", "पैसे गिनना और बाक़ी पैसे"], "sv": ["Count your change", "🧾"], "st": ["Kabir buys a notebook for ₹35 and gives the shopkeeper a ₹50 note. The shopkeeper gives back ₹15 as change: a ₹10 note and a ₹5 coin. Kabir counts it right there. He also checks the bill: notebook ₹35, total ₹35, paid ₹50, change ₹15. Counting before he leaves the counter means no mistake goes home with him.", "कबीर दुकान से ₹35 की कॉपी ख़रीदता है और दुकानदार को ₹50 का नोट देता है। दुकानदार ₹15 वापस देता है: एक ₹10 का नोट और एक ₹5 का सिक्का। कबीर वहीं गिनकर देखता है। वह बिल भी जाँचता है: कॉपी ₹35, कुल ₹35, दिया ₹50, वापसी ₹15। काउंटर पर ही गिन लेने से कोई ग़लती घर नहीं जाती।"], "kn": [["Change is the money you get back when you pay more than the price: change = money given − price.", "You can count up from the price: ₹35 to ₹40 is ₹5, then to ₹50 is ₹10, so ₹15 in all.", "A bill or receipt lists what you bought, each price, the total and what you paid. Keep it in case you need to return something or complain.", "Always count your change before you walk away, and say thank you."], ["बाक़ी पैसे (चेंज) वे पैसे हैं जो दाम से ज़्यादा देने पर वापस मिलते हैं: बाक़ी = दिया हुआ पैसा − दाम।", "दाम से ऊपर गिनते हुए भी निकाल सकते हैं: ₹35 से ₹40 तक ₹5, फिर ₹50 तक ₹10, यानी कुल ₹15।", "बिल या रसीद में लिखा होता है कि आपने क्या ख़रीदा, हर चीज़ का दाम, कुल रक़म और आपने कितना दिया। सामान लौटाना या शिकायत करनी हो तो उसे संभालकर रखें।", "दुकान से हटने से पहले अपने बाक़ी पैसे गिन लें और धन्यवाद कहें।"]], "qz": [["You pay ₹20 for a ₹12 eraser set. How much change do you get?", "आप ₹12 के रबर-सेट के लिए ₹20 देते हैं। आपको कितने बाक़ी पैसे मिलेंगे?", ["₹6", "₹8", "₹10", "₹32"], null, 1], ["Change is…", "बाक़ी पैसे (चेंज) का मतलब है…", ["Money you get back when you pay more", "The price of the item", "A kind of coin only"], ["ज़्यादा देने पर वापस मिलने वाला पैसा", "सामान का दाम", "सिर्फ़ एक तरह का सिक्का"], 0], ["What does a bill or receipt show?", "बिल या रसीद में क्या लिखा होता है?", ["What you bought, its price and the total", "Only the shop’s name", "Only the date"], ["क्या ख़रीदा, उसका दाम और कुल रक़म", "सिर्फ़ दुकान का नाम", "सिर्फ़ तारीख़"], 0], ["Two ₹10 notes and one ₹5 coin make…", "दो ₹10 के नोट और एक ₹5 का सिक्का मिलकर होते हैं…", ["₹15", "₹20", "₹25", "₹30"], null, 2], ["You buy things worth ₹18 and ₹27. What is the total?", "आप ₹18 और ₹27 का सामान ख़रीदते हैं। कुल कितना हुआ?", ["₹35", "₹45", "₹55", "₹9"], null, 1], ["You pay ₹100 for a ₹64 toy. How much change?", "आप ₹64 के खिलौने के लिए ₹100 देते हैं। कितने बाक़ी पैसे मिलेंगे?", ["₹26", "₹36", "₹46", "₹164"], null, 1], ["The shopkeeper gives you less change than you should get. What should you do?", "दुकानदार ने आपको कम बाक़ी पैसे लौटाए। आपको क्या करना चाहिए?", ["Politely tell the shopkeeper and ask them to check", "Shout and run away", "Say nothing and go home"], ["नम्रता से दुकानदार को बताकर दोबारा गिनने को कहना", "चिल्लाकर भाग जाना", "चुपचाप घर चले जाना"], 0]]}, {"id": "c2", "l": 0, "n": ["Where money comes from", "पैसा कहाँ से आता है"], "sv": ["Work earns money", "👩‍🌾"], "st": ["Ria wonders where the money in her father’s wallet comes from. He drives a school bus: he carries children and the school pays him for it. A farmer grows wheat and sells it. The baker turns wheat into bread and sells it. The tailor sews clothes. Everyone does some work that others need, and gets paid for it. Long ago people simply swapped things, called barter, but now money lets all these people trade easily.", "रिया सोचती है कि पापा के बटुए में पैसे कहाँ से आते हैं। वे स्कूल बस चलाते हैं: बच्चों को ले जाते हैं और स्कूल उन्हें इसके पैसे देता है। किसान गेहूँ उगाकर बेचता है। नानबाई गेहूँ से रोटी-ब्रेड बनाकर बेचता है। दर्ज़ी कपड़े सिलता है। हर कोई ऐसा काम करता है जो दूसरों को चाहिए, और उसके बदले पैसे पाता है। बहुत पहले लोग चीज़ों की अदला-बदली करते थे, जिसे वस्तु-विनिमय (बार्टर) कहते हैं, पर अब पैसे से ये सब आसानी से लेन-देन करते हैं।"], "kn": [["People earn money by doing work that others need: a farmer grows food, a teacher teaches, a driver carries people.", "A good is a thing you can touch (bread, a pen). A service is work done for you (a haircut, a bus ride).", "Money moves in a circle: you pay a shopkeeper, the shopkeeper pays a supplier, the supplier pays a farmer.", "All honest work is useful. Different jobs earn different amounts, depending on skill, time and need."], ["लोग ऐसा काम करके पैसे कमाते हैं जो दूसरों को चाहिए: किसान अनाज उगाता है, शिक्षक पढ़ाता है, ड्राइवर लोगों को ले जाता है।", "वस्तु वह चीज़ है जिसे आप छू सकते हैं (रोटी, पेन)। सेवा वह काम है जो आपके लिए किया जाए (बाल कटवाना, बस की सवारी)।", "पैसा घूमता रहता है: आप दुकानदार को देते हैं, दुकानदार सप्लायर को, और सप्लायर किसान को।", "हर ईमानदार काम उपयोगी है। हुनर, समय और ज़रूरत के हिसाब से अलग-अलग काम की कमाई अलग होती है।"]], "qz": [["Who earns money by growing wheat?", "गेहूँ उगाकर कौन कमाता है?", ["A farmer", "A toy", "A coin"], ["किसान", "खिलौना", "सिक्का"], 0], ["A haircut is a…", "बाल कटवाना एक… है", ["Service", "Good", "Coin"], ["सेवा", "वस्तु", "सिक्का"], 0], ["A pen is a…", "पेन एक… है", ["Good", "Service", "Job"], ["वस्तु", "सेवा", "नौकरी"], 0], ["Which of these is a service?", "इनमें से सेवा कौन-सी है?", ["A bus ride", "A loaf of bread", "A school bag"], ["बस की सवारी", "डबलरोटी", "स्कूल बैग"], 0], ["Swapping things without money is called…", "बिना पैसे के चीज़ों की अदला-बदली कहलाती है…", ["Barter", "Banking", "Budget"], ["वस्तु-विनिमय (बार्टर)", "बैंकिंग", "बजट"], 0], ["The baker buys wheat and sells bread. This shows…", "नानबाई गेहूँ ख़रीदकर रोटी-ब्रेड बेचता है। यह दिखाता है…", ["Money moving between people who work", "Money disappearing", "Only the baker needs money"], ["काम करने वालों के बीच पैसे का आना-जाना", "पैसे का ग़ायब हो जाना", "सिर्फ़ नानबाई को पैसा चाहिए"], 0], ["Why do different jobs earn different amounts?", "अलग-अलग काम की कमाई अलग क्यों होती है?", ["Skill, time and need differ", "Because of the colour of clothes", "No reason at all"], ["हुनर, समय और ज़रूरत अलग होती है", "कपड़ों के रंग की वजह से", "कोई कारण नहीं"], 0]]}, {"id": "c3", "l": 1, "n": ["Comparing prices and offers", "दाम और ऑफ़र की तुलना"], "sv": ["Compare before you buy", "⚖️"], "st": ["Dev wants a pack of pencils. Shop A sells 10 pencils for ₹50. Shop B sells 12 pencils for ₹48. Dev finds the price of one pencil: ₹5 at Shop A and ₹4 at Shop B. Shop B is cheaper. A sign says “Buy 1 get 1 free” on a ₹30 sharpener box he does not need. Dev knows a free item is not a saving if he never wanted it, so he walks past. Another shop gives ₹10 off a ₹100 bag, so he pays ₹90.", "देव को पेंसिलों का पैकेट चाहिए। दुकान A में 10 पेंसिल ₹50 की हैं। दुकान B में 12 पेंसिल ₹48 की हैं। देव एक पेंसिल का दाम निकालता है: दुकान A में ₹5 और दुकान B में ₹4। दुकान B सस्ती है। एक बोर्ड पर लिखा है “एक ख़रीदें, एक मुफ़्त”, पर वह ₹30 का शार्पनर-बॉक्स उसे चाहिए ही नहीं। देव जानता है कि जो चीज़ चाहिए ही नहीं, वह मुफ़्त मिले तब भी बचत नहीं है, इसलिए वह आगे बढ़ जाता है। एक और दुकान ₹100 के बैग पर ₹10 की छूट देती है, तो वह ₹90 देता है।"], "kn": [["To compare, find the price of one: price ÷ number of items. ₹48 for 12 is ₹4 each.", "The lower price of one is the cheaper deal, if the quality is the same.", "A discount (or offer) lowers the price: ₹100 with ₹10 off becomes ₹90. “Buy 1 get 1 free” means two items for the price of one.", "An offer is a saving only if you really need the thing. Buying what you do not need just to get the offer wastes money."], ["तुलना के लिए एक चीज़ का दाम निकालें: दाम ÷ चीज़ों की गिनती। 12 के ₹48 यानी एक का ₹4।", "अगर गुणवत्ता बराबर हो तो जिसका एक का दाम कम है, वही सौदा सस्ता है।", "छूट (डिस्काउंट) या ऑफ़र दाम घटाता है: ₹100 पर ₹10 की छूट से ₹90 हो जाता है। “एक ख़रीदें, एक मुफ़्त” का मतलब है एक के दाम में दो चीज़ें।", "ऑफ़र तभी बचत है जब चीज़ सचमुच चाहिए हो। जो चीज़ ज़रूरी नहीं, उसे सिर्फ़ ऑफ़र के लिए ख़रीदना पैसे की बर्बादी है।"]], "qz": [["10 pencils cost ₹50. What does one pencil cost?", "10 पेंसिल ₹50 की हैं। एक पेंसिल का दाम क्या है?", ["₹4", "₹5", "₹10", "₹50"], null, 1], ["12 pencils cost ₹48. What does one pencil cost?", "12 पेंसिल ₹48 की हैं। एक पेंसिल का दाम क्या है?", ["₹3", "₹4", "₹6", "₹12"], null, 1], ["Which shop is cheaper per pencil?", "प्रति पेंसिल कौन-सी दुकान सस्ती है?", ["Shop A (₹5 each)", "Shop B (₹4 each)", "Both are the same"], ["दुकान A (एक का ₹5)", "दुकान B (एक का ₹4)", "दोनों बराबर"], 1], ["A ₹100 bag has ₹10 off. You pay…", "₹100 के बैग पर ₹10 की छूट है। आप देंगे…", ["₹10", "₹90", "₹110", "₹100"], null, 1], ["“Buy 1 get 1 free” on a ₹30 item. You pay for 2 items…", "₹30 की चीज़ पर “एक ख़रीदें, एक मुफ़्त”। 2 चीज़ों के लिए आप देंगे…", ["₹30", "₹60", "₹15", "₹90"], null, 0], ["You do not need a toy but it is on offer. The smart choice is…", "आपको खिलौना नहीं चाहिए, पर उस पर ऑफ़र है। समझदारी है…", ["Do not buy it", "Buy it because it is cheap", "Buy two"], ["उसे न ख़रीदना", "सस्ता है इसलिए ख़रीद लेना", "दो ख़रीद लेना"], 0], ["A pack of 6 costs ₹30 and a pack of 10 costs ₹40. Which is cheaper per item?", "6 का पैक ₹30 का और 10 का पैक ₹40 का है। प्रति चीज़ कौन-सा सस्ता है?", ["Pack of 6 (₹5 each)", "Pack of 10 (₹4 each)", "Both are the same"], ["6 का पैक (एक का ₹5)", "10 का पैक (एक का ₹4)", "दोनों बराबर"], 1]]}, {"id": "c4", "l": 1, "n": ["Piggy bank and sharing", "गुल्लक और बाँटना"], "sv": ["Save · Spend · Share", "🐷"], "st": ["Anaya gets ₹100 on her birthday. Her mother shows her three jars. Anaya puts ₹50 in Spend, ₹30 in Save and ₹20 in Share. With the Share money she buys biscuits for a dog shelter near her school. The Save money goes into her piggy bank, so she can buy a bicycle bell. Waiting is hard, but after three months the bell is hers and she feels proud.", "अनाया को जन्मदिन पर ₹100 मिलते हैं। माँ उसे तीन डिब्बे दिखाती हैं। अनाया “ख़र्च” में ₹50, “बचत” में ₹30 और “बाँटना” में ₹20 डालती है। बाँटने वाले पैसों से वह स्कूल के पास कुत्तों के आश्रय के लिए बिस्कुट ख़रीदती है। बचत वाले पैसे गुल्लक में जाते हैं, ताकि वह साइकिल की घंटी ख़रीद सके। इंतज़ार मुश्किल है, पर तीन महीने बाद घंटी उसकी हो जाती है और उसे गर्व होता है।"], "kn": [["A piggy bank (gullak) helps you keep money safe for later instead of spending it at once.", "Try three jars: Spend (for now), Save (for later) and Share (for others).", "Waiting to buy something you want is called patience. It helps you save enough for bigger things.", "Sharing can be money, time or help. Giving a little to someone in need makes your community stronger."], ["गुल्लक आपके पैसे बाद के लिए सुरक्षित रखने में मदद करती है, ताकि वे एक बार में ख़र्च न हो जाएँ।", "तीन डिब्बे आज़माएँ: ख़र्च (अभी के लिए), बचत (बाद के लिए) और बाँटना (दूसरों के लिए)।", "जो चीज़ चाहिए उसे ख़रीदने के लिए इंतज़ार करना धैर्य कहलाता है। इससे बड़ी चीज़ों के लिए पर्याप्त पैसे जमा हो जाते हैं।", "बाँटना पैसे, समय या मदद के रूप में हो सकता है। ज़रूरतमंद को थोड़ा देने से आपका समाज मज़बूत बनता है।"]], "qz": [["A gullak is used to…", "गुल्लक किसलिए होती है?", ["Keep money safe for later", "Throw money away", "Hide homework"], ["पैसे बाद के लिए सुरक्षित रखना", "पैसे फेंक देना", "होमवर्क छिपाना"], 0], ["The three jars are Spend, Save and…", "तीन डिब्बे हैं ख़र्च, बचत और…", ["Share", "Lose", "Hide"], ["बाँटना", "खोना", "छिपाना"], 0], ["Money in the Save jar is meant for…", "बचत वाले डिब्बे का पैसा किसके लिए है?", ["Later", "Today only", "Throwing away"], ["बाद के लिए", "सिर्फ़ आज के लिए", "फेंकने के लिए"], 0], ["Anaya puts ₹50 in Spend and ₹30 in Save out of ₹100. How much is left for Share?", "अनाया ₹100 में से ₹50 ख़र्च में और ₹30 बचत में डालती है। बाँटने के लिए कितना बचा?", ["₹10", "₹20", "₹30", "₹50"], null, 1], ["Waiting and not buying everything at once is called…", "इंतज़ार करना और सब कुछ एक साथ न ख़रीदना कहलाता है…", ["Patience", "Hurry", "Offer"], ["धैर्य", "जल्दबाज़ी", "ऑफ़र"], 0], ["You save ₹10 every week. How much after 5 weeks?", "आप हर हफ़्ते ₹10 बचाते हैं। 5 हफ़्ते बाद कितना होगा?", ["₹15", "₹50", "₹5", "₹510"], null, 1], ["Sharing can be…", "बाँटना हो सकता है…", ["Money, time or help", "Only money", "Only toys"], ["पैसे, समय या मदद", "सिर्फ़ पैसे", "सिर्फ़ खिलौने"], 0]]}, {"id": "c5", "l": 2, "n": ["Buying and selling: profit and loss", "ख़रीदना-बेचना: लाभ और हानि"], "sv": ["Profit or loss?", "🍋"], "st": ["Samar runs a lemonade stall at the school fair. He spends ₹100 on lemons, sugar and cups. This is his cost. He sells all the glasses for ₹150. The money he gets from selling is the selling price. Because ₹150 is more than ₹100, he makes a profit of ₹50. The next week he spends ₹100 again, but it rains and he sells only ₹80 worth. Now he gets less than he spent, so he has a loss of ₹20. A shopkeeper wants a profit, so he sells for more than he paid.", "समर स्कूल के मेले में नींबू-पानी का स्टॉल लगाता है। नींबू, चीनी और गिलास पर वह ₹100 ख़र्च करता है। यह उसकी लागत है। वह सारे गिलास ₹150 में बेच देता है। बेचकर जो पैसा मिलता है, वह बिक्री-मूल्य है। ₹150, ₹100 से ज़्यादा है, इसलिए ₹50 का लाभ हुआ। अगले हफ़्ते वह फिर ₹100 ख़र्च करता है, पर बारिश हो जाती है और सिर्फ़ ₹80 का सामान बिकता है। अब जितना ख़र्च किया उससे कम मिला, इसलिए ₹20 की हानि हुई। दुकानदार लाभ चाहता है, इसलिए वह ख़रीद से ज़्यादा दाम पर बेचता है।"], "kn": [["Cost price (CP) is what you pay to buy or make something. Selling price (SP) is what you get when you sell it.", "If SP is more than CP, you make a profit: profit = SP − CP.", "If SP is less than CP, you have a loss: loss = CP − SP.", "If SP equals CP there is no profit and no loss. Shops add a small profit so they can pay rent, helpers and their own family."], ["क्रय-मूल्य (CP) वह है जो आप कोई चीज़ ख़रीदने या बनाने में लगाते हैं। विक्रय-मूल्य (SP) वह है जो उसे बेचने पर मिलता है।", "अगर SP, CP से ज़्यादा है तो लाभ होता है: लाभ = SP − CP।", "अगर SP, CP से कम है तो हानि होती है: हानि = CP − SP।", "अगर SP और CP बराबर हों तो न लाभ, न हानि। दुकानदार थोड़ा लाभ जोड़ते हैं ताकि किराया, मददगारों का वेतन और अपना घर चला सकें।"]], "qz": [["Samar spends ₹100 and sells for ₹150. This is a…", "समर ₹100 ख़र्च करता है और ₹150 में बेचता है। यह है…", ["Profit", "Loss", "Neither"], ["लाभ", "हानि", "दोनों में से कुछ नहीं"], 0], ["The money you spend to get an item is the…", "किसी चीज़ को पाने में लगाया गया पैसा कहलाता है…", ["Cost price", "Selling price", "Change"], ["क्रय-मूल्य", "विक्रय-मूल्य", "बाक़ी पैसे"], 0], ["You sell an item for ₹40 that cost you ₹40. There is…", "जो चीज़ आपको ₹40 में पड़ी, उसे आप ₹40 में बेचते हैं। तब होता है…", ["No profit, no loss", "Profit", "Loss"], ["न लाभ, न हानि", "लाभ", "हानि"], 0], ["You buy for ₹60 and sell for ₹75. What is the profit?", "आप ₹60 में ख़रीदकर ₹75 में बेचते हैं। लाभ कितना हुआ?", ["₹5", "₹15", "₹25", "₹135"], null, 1], ["You buy for ₹80 and sell for ₹65. What is the loss?", "आप ₹80 में ख़रीदकर ₹65 में बेचते हैं। हानि कितनी हुई?", ["₹5", "₹15", "₹25", "₹145"], null, 1], ["Samar’s cost was ₹100 and he sold ₹80 worth. His result is…", "समर की लागत ₹100 थी और ₹80 का सामान बिका। नतीजा है…", ["A loss of ₹20", "A profit of ₹20", "A profit of ₹180"], ["₹20 की हानि", "₹20 का लाभ", "₹180 का लाभ"], 0], ["Why do shopkeepers sell for more than they paid?", "दुकानदार ख़रीद से ज़्यादा दाम पर क्यों बेचते हैं?", ["To earn a profit and run the shop", "To confuse customers", "They do not"], ["लाभ कमाने और दुकान चलाने के लिए", "ग्राहकों को उलझाने के लिए", "वे ऐसा नहीं करते"], 0]]}, {"id": "c6", "l": 3, "n": ["Online games and in-app purchases", "ऑनलाइन गेम और ऐप के अंदर ख़रीदारी"], "sv": ["Free game, hidden cost", "🎮"], "st": ["Veer is playing a free racing game on his father’s phone. A pop-up says, “Buy 100 gems for ₹99 to win faster!” Veer’s thumb is near the button. He remembers the rule: tap Buy only after asking an adult. Real money leaves the account when you buy something in a game, even if the game was free. He closes the pop-up and tells his father, who turns on a purchase password so no one buys by mistake.", "वीर पापा के फ़ोन पर एक मुफ़्त रेसिंग गेम खेल रहा है। एक पॉप-अप आता है: “जीतने के लिए ₹99 में 100 जेम्स ख़रीदें!” वीर का अँगूठा बटन के पास है। उसे नियम याद आता है: “ख़रीदें” दबाने से पहले किसी बड़े से पूछना है। गेम मुफ़्त हो तब भी उसके अंदर कुछ ख़रीदने पर असली पैसे खाते से कट जाते हैं। वह पॉप-अप बंद कर देता है और पापा को बताता है। पापा ख़रीदारी के लिए पासवर्ड लगा देते हैं ताकि ग़लती से कोई कुछ न ख़रीदे।"], "kn": [["“Free” games can still ask you to spend real money on gems, coins, skins or extra lives. These are called in-app purchases.", "Ask an adult before you tap Buy. Never use someone’s card or UPI without permission.", "Games are designed to keep you playing and spending. Set a play time and take breaks.", "India has banned online games played for real money (betting). If a game asks you to put in money to win money, leave it and tell an adult."], ["“मुफ़्त” गेम भी जेम्स, सिक्कों, स्किन या अतिरिक्त जान के लिए असली पैसे माँग सकते हैं। इन्हें ऐप के अंदर की ख़रीदारी (इन-ऐप पर्चेज़) कहते हैं।", "“ख़रीदें” दबाने से पहले किसी बड़े से पूछें। बिना इजाज़त किसी का कार्ड या UPI कभी इस्तेमाल न करें।", "गेम इस तरह बनाए जाते हैं कि आप खेलते और ख़र्च करते रहें। खेलने का समय तय करें और बीच-बीच में आराम लें।", "भारत में असली पैसे लगाकर खेले जाने वाले ऑनलाइन गेम (सट्टा) पर रोक है। जो गेम पैसा जीतने के लिए पैसा लगाने को कहे, उसे छोड़ दें और किसी बड़े को बताएँ।"]], "qz": [["A pop-up asks you to buy gems in a game. First, you should…", "गेम में पॉप-अप जेम्स ख़रीदने को कहता है। सबसे पहले आपको…", ["Ask an adult", "Tap Buy quickly", "Share the PIN"], ["किसी बड़े से पूछना चाहिए", "जल्दी से ख़रीदें दबाना चाहिए", "पिन बता देना चाहिए"], 0], ["In-app purchases use…", "ऐप के अंदर की ख़रीदारी में लगता है…", ["Real money", "Pretend money", "No money"], ["असली पैसा", "नक़ली पैसा", "कोई पैसा नहीं"], 0], ["A “free” game can still…", "एक “मुफ़्त” गेम फिर भी…", ["Ask for real money inside", "Cost nothing ever", "Be a bank"], ["अंदर असली पैसे माँग सकता है", "कभी कुछ नहीं लेता", "बैंक होता है"], 0], ["A game costs ₹99 for 100 gems. How much for 200 gems at the same rate?", "एक गेम में 100 जेम्स ₹99 के हैं। उसी दर पर 200 जेम्स कितने के होंगे?", ["₹99", "₹148", "₹198", "₹298"], null, 2], ["Why should you set a play-time limit?", "खेलने का समय-सीमा क्यों तय करनी चाहिए?", ["Games are made to keep you playing and spending", "Games are always bad", "Phones get angry"], ["गेम इस तरह बनते हैं कि आप खेलते और ख़र्च करते रहें", "गेम हमेशा बुरे होते हैं", "फ़ोन नाराज़ हो जाते हैं"], 0], ["A game says “Put in ₹50 to win ₹500”. This is…", "एक गेम कहता है “₹50 लगाइए, ₹500 जीतिए”। यह है…", ["Betting, so leave it and tell an adult", "A great saving plan", "A bank scheme"], ["सट्टा, इसलिए छोड़ दें और किसी बड़े को बताएँ", "बचत की बढ़िया योजना", "बैंक की योजना"], 0], ["After a mistaken purchase you should…", "ग़लती से कुछ ख़रीद लेने के बाद आपको…", ["Tell an adult at once", "Hide it", "Buy more"], ["तुरंत किसी बड़े को बताना चाहिए", "छिपा लेना चाहिए", "और ख़रीद लेना चाहिए"], 0]]}];
var NEW11=[{"id": "b1", "l": 1, "n": ["Profit, loss and margin", "लाभ, हानि और मार्जिन"], "sv": "bars", "st": ["Nisha buys 20 notebooks at ₹30 each (cost ₹600) and sells them to classmates at ₹40 each. The sales bring in ₹800, so the profit is ₹200. Profit % = profit ÷ cost × 100 = 200 ÷ 600 × 100, about 33%. Her friend Omar sells stationery for ₹800 that cost him ₹900. That is a loss of ₹100, or about 11% of cost. Profit looks real only after counting every cost: Nisha also spent ₹50 on bus fare to the wholesale shop, so her real profit is ₹150.", "निशा 20 कॉपियाँ ₹30 प्रति कॉपी के हिसाब से ख़रीदती है (लागत ₹600) और सहपाठियों को ₹40 प्रति कॉपी में बेचती है। बिक्री से ₹800 आते हैं, इसलिए लाभ ₹200 हुआ। लाभ % = लाभ ÷ लागत × 100 = 200 ÷ 600 × 100, यानी लगभग 33%। उसके दोस्त उमर ने ₹900 में ख़रीदी स्टेशनरी ₹800 में बेची। यह ₹100 की हानि है, यानी लागत का लगभग 11%। लाभ तभी असली दिखता है जब हर लागत जोड़ी जाए: निशा ने थोक दुकान तक जाने में ₹50 बस-किराया भी ख़र्च किया था, इसलिए उसका असली लाभ ₹150 है।"], "kn": [["Cost price (CP) is what you pay. Selling price (SP) is what you receive. Profit = SP − CP. Loss = CP − SP.", "Profit % = profit ÷ CP × 100. Loss % = loss ÷ CP × 100. These percentages are always worked out on the cost price.", "Count every cost: transport, packing, rent and your own time. Profit after all costs is your real profit.", "Margin tells you how much of the selling price is profit: profit ÷ SP × 100. A shop with a 20% margin keeps ₹20 from every ₹100 it sells."], ["क्रय-मूल्य (CP) वह है जो आप चुकाते हैं। विक्रय-मूल्य (SP) वह है जो आपको मिलता है। लाभ = SP − CP। हानि = CP − SP।", "लाभ % = लाभ ÷ CP × 100। हानि % = हानि ÷ CP × 100। ये प्रतिशत हमेशा क्रय-मूल्य पर निकाले जाते हैं।", "हर लागत गिनें: ढुलाई, पैकिंग, किराया और अपना समय। सारी लागत के बाद बचा लाभ ही असली लाभ है।", "मार्जिन बताता है कि बिक्री-मूल्य का कितना हिस्सा लाभ है: लाभ ÷ SP × 100। 20% मार्जिन वाली दुकान हर ₹100 की बिक्री में ₹20 रखती है।"]], "qz": [["CP ₹250, SP ₹300. What is the profit?", "CP ₹250, SP ₹300। लाभ कितना है?", ["₹25", "₹50", "₹550", "₹300"], null, 1], ["CP ₹200, SP ₹250. The profit percent is…", "CP ₹200, SP ₹250। लाभ प्रतिशत है…", ["20%", "25%", "50%", "10%"], null, 1], ["An item bought for ₹500 is sold for ₹450. The loss percent is…", "₹500 में ख़रीदी चीज़ ₹450 में बिकी। हानि प्रतिशत है…", ["5%", "10%", "50%", "90%"], null, 1], ["Profit % is worked out on the…", "लाभ % किस पर निकाला जाता है?", ["Cost price", "Selling price", "Number of customers"], ["क्रय-मूल्य", "विक्रय-मूल्य", "ग्राहकों की संख्या"], 0], ["Nisha’s notebooks bring ₹800 against ₹600 of cost, plus ₹50 transport. Her real profit is…", "निशा की कॉपियों से ₹800 आए, लागत ₹600 और ढुलाई ₹50। उसका असली लाभ है…", ["₹200", "₹150", "₹250", "₹50"], null, 1]]}, {"id": "b2", "l": 1, "n": ["Discounts, GST and percentages", "छूट, GST और प्रतिशत"], "sv": "scale", "st": ["Mehul sees headphones marked ₹2,000 with “25% off”. 10% of ₹2,000 is ₹200, so 25% is ₹500 and the discounted price is ₹1,500. At the counter the bill adds GST at 18%: 18% of ₹1,500 is ₹270, so he pays ₹1,770. Another shop lists the same pair at ₹1,650 with “GST extra”. Adding 18% GST of ₹297 makes it ₹1,947, which is more. Mehul learns to compare the final bill, not the sticker.", "मेहुल को ₹2,000 के निशान वाला हेडफ़ोन “25% छूट” के साथ दिखता है। ₹2,000 का 10% ₹200 होता है, इसलिए 25% ₹500 हुआ और छूट के बाद दाम ₹1,500 है। काउंटर पर बिल में 18% GST जुड़ता है: ₹1,500 का 18% ₹270 है, तो वह ₹1,770 चुकाता है। दूसरी दुकान वही हेडफ़ोन ₹1,650 में “GST अलग से” लिखकर बेचती है। 18% GST के ₹297 जोड़ने पर वह ₹1,947 बैठता है, यानी ज़्यादा। मेहुल सीखता है कि स्टिकर नहीं, आख़िरी बिल की तुलना करनी चाहिए।"], "kn": [["Percent means “out of 100”. 10% of ₹2,000 is ₹200. Find 10% first, then build other percentages from it.", "Discount = marked price × discount % ÷ 100. Final price = marked price − discount.", "GST (Goods and Services Tax) is added to the bill on most goods and services. The rate depends on the item (common rates are 5% and 18%; some essentials have 0%).", "Always compare the final amount on the bill, including GST and any delivery or packing charge."], ["प्रतिशत का मतलब है “सैकड़े में”। ₹2,000 का 10% ₹200 है। पहले 10% निकालें, फिर उसी से बाक़ी प्रतिशत बनाएँ।", "छूट = अंकित मूल्य × छूट % ÷ 100। अंतिम दाम = अंकित मूल्य − छूट।", "GST (वस्तु एवं सेवा कर) ज़्यादातर सामान और सेवाओं के बिल में जुड़ता है। दर वस्तु पर निर्भर है (आम दरें 5% और 18% हैं; कुछ ज़रूरी चीज़ों पर 0%)।", "हमेशा बिल की अंतिम रक़म की तुलना करें, जिसमें GST और डिलीवरी या पैकिंग का शुल्क भी हो।"]], "qz": [["What is 10% of ₹800?", "₹800 का 10% कितना है?", ["₹8", "₹80", "₹100", "₹400"], null, 1], ["A ₹1,000 jacket has 20% off. The price becomes…", "₹1,000 की जैकेट पर 20% छूट है। दाम हो जाता है…", ["₹200", "₹800", "₹980", "₹1,200"], null, 1], ["A ₹500 item gets 18% GST added. The bill is…", "₹500 की चीज़ पर 18% GST जुड़ता है। बिल होता है…", ["₹518", "₹590", "₹680", "₹90"], null, 1], ["GST is…", "GST है…", ["A tax added on goods and services", "A bank loan", "A kind of discount"], ["सामान और सेवाओं पर जुड़ने वाला कर", "बैंक का लोन", "एक तरह की छूट"], 0], ["To pick the better deal you should compare…", "बेहतर सौदा चुनने के लिए तुलना करें…", ["The final amount on the bill", "Only the sticker price", "The shop’s colour"], ["बिल की अंतिम रक़म की", "सिर्फ़ स्टिकर के दाम की", "दुकान के रंग की"], 0]]}, {"id": "b3", "l": 2, "n": ["Starting a small business", "छोटा व्यवसाय शुरू करना"], "sv": "coin", "st": ["Tara and Kabir plan a weekend snack stall. Fixed costs: ₹300 for the stall and banner. Each plate costs ₹20 to make and sells for ₹50, so every plate gives ₹30 of profit before the fixed costs. To cover ₹300 they must sell 10 plates: this is the break-even point. After the 10th plate, every plate adds ₹30. They sell 40 plates: ₹30 × 40 = ₹1,200, minus ₹300 leaves ₹900 profit, shared between the two.", "तारा और कबीर सप्ताहांत में नाश्ते का स्टॉल लगाने की योजना बनाते हैं। स्थिर लागत: स्टॉल और बैनर के ₹300। हर प्लेट बनाने में ₹20 लगते हैं और ₹50 में बिकती है, यानी स्थिर लागत से पहले हर प्लेट ₹30 का लाभ देती है। ₹300 निकालने के लिए उन्हें 10 प्लेटें बेचनी होंगी: यही सम-विच्छेद बिंदु (ब्रेक-ईवन) है। 10वीं प्लेट के बाद हर प्लेट ₹30 जोड़ती है। वे 40 प्लेटें बेचते हैं: ₹30 × 40 = ₹1,200, उसमें से ₹300 घटाने पर ₹900 का लाभ बचता है, जो दोनों में बँटता है।"], "kn": [["Fixed costs stay the same however much you sell (stall, banner). Variable costs rise with each item (ingredients).", "Profit per item = selling price − variable cost per item.", "Break-even = fixed costs ÷ profit per item. Below that number you lose, above it you earn.", "Before you start: know your customers, price fairly, keep a record of every rupee and do not borrow more than you can repay. If you sell food, check local rules such as food safety."], ["स्थिर लागत उतनी ही रहती है चाहे आप कितना भी बेचें (स्टॉल, बैनर)। परिवर्तनशील लागत हर चीज़ के साथ बढ़ती है (सामग्री)।", "प्रति चीज़ लाभ = बिक्री-मूल्य − प्रति चीज़ परिवर्तनशील लागत।", "सम-विच्छेद बिंदु (ब्रेक-ईवन) = स्थिर लागत ÷ प्रति चीज़ लाभ। इस संख्या से नीचे हानि होती है, ऊपर कमाई।", "शुरू करने से पहले ग्राहकों को जानें, दाम ठीक रखें, हर रुपये का हिसाब लिखें और चुकाने से ज़्यादा उधार न लें। खाने का सामान बेचें तो खाद्य सुरक्षा जैसे स्थानीय नियम देख लें।"]], "qz": [["A plate costs ₹20 to make and sells for ₹50. The profit per plate is…", "एक प्लेट बनाने में ₹20 लगते हैं और वह ₹50 में बिकती है। प्रति प्लेट लाभ है…", ["₹20", "₹30", "₹50", "₹70"], null, 1], ["Fixed costs are…", "स्थिर लागत वह है…", ["Costs that stay the same however much you sell", "Costs that change with every item", "Money from customers"], ["जो आप कितना भी बेचें, उतनी ही रहती है", "जो हर चीज़ के साथ बदलती है", "जो ग्राहकों से मिलता है"], 0], ["Fixed cost ₹300 and profit per plate ₹30. Break-even is…", "स्थिर लागत ₹300 और प्रति प्लेट लाभ ₹30। ब्रेक-ईवन है…", ["5 plates", "10 plates", "30 plates", "300 plates"], ["5 प्लेट", "10 प्लेट", "30 प्लेट", "300 प्लेट"], 1], ["They sell 40 plates at ₹30 profit each, with ₹300 fixed costs. The total profit is…", "वे 40 प्लेटें बेचते हैं, हर प्लेट पर ₹30 लाभ, स्थिर लागत ₹300। कुल लाभ है…", ["₹900", "₹1,200", "₹1,500", "₹300"], null, 0], ["Which is a good habit for a new business?", "नए व्यवसाय के लिए अच्छी आदत कौन-सी है?", ["Record every rupee", "Borrow as much as possible", "Ignore costs"], ["हर रुपये का हिसाब लिखना", "जितना हो सके उधार लेना", "लागत को अनदेखा करना"], 0]]}, {"id": "b4", "l": 2, "n": ["Pricing tricks, ads and betting apps", "दाम की चालें, विज्ञापन और सट्टा-ऐप"], "sv": "phone", "st": ["Rahul scrolls past an ad: “Sneakers ₹999 only!” ₹999 feels far below ₹1,000, but it is just ₹1 less. A banner says “Only 2 left!” and a timer is counting down. An influencer says, “Download this app, play and win ₹10,000 in minutes.” Rahul’s friend has already lost ₹1,500 on a similar app. Rahul knows real-money games are banned in India under a 2025 law, and that such an app may also be a scam. He closes it, waits a day and then decides whether he still needs the sneakers.", "राहुल स्क्रॉल करते हुए एक विज्ञापन देखता है: “स्नीकर्स सिर्फ़ ₹999 में!” ₹999 ₹1,000 से काफ़ी कम लगता है, पर असल में सिर्फ़ ₹1 कम है। एक बैनर कहता है “सिर्फ़ 2 बचे हैं!” और टाइमर उलटी गिनती कर रहा है। एक इन्फ़्लुएंसर कहता है, “यह ऐप डाउनलोड करें, खेलें और मिनटों में ₹10,000 जीतें।” राहुल का दोस्त ऐसे ही एक ऐप पर ₹1,500 हार चुका है। राहुल जानता है कि भारत में असली पैसे वाले गेम 2025 के क़ानून से प्रतिबंधित हैं, और ऐसा ऐप धोखा भी हो सकता है। वह उसे बंद कर देता है, एक दिन इंतज़ार करता है और फिर तय करता है कि स्नीकर्स अब भी चाहिए या नहीं।"], "kn": [["Shops use tricks: ₹999 instead of ₹1,000, “limited stock”, countdown timers, “free” gifts that need a purchase. Pause and compare.", "Ads and influencers are often paid to sell. Ask: what do they gain if I buy?", "Betting, fantasy-for-money and gambling apps are designed so that most people lose. India’s Online Gaming Act, 2025 bans online games played for real money.", "Teens should never bet, and should never share OTPs or bank details to “win” or “claim” money. If you or a friend is in trouble, tell a trusted adult."], ["दुकानें चालें चलती हैं: ₹1,000 की जगह ₹999, “सीमित स्टॉक”, उलटी गिनती वाले टाइमर, “मुफ़्त” उपहार जो ख़रीदारी पर मिलें। रुकें और तुलना करें।", "विज्ञापन और इन्फ़्लुएंसर अक्सर बेचने के लिए पैसे पाते हैं। पूछें: मेरे ख़रीदने से इन्हें क्या फ़ायदा है?", "सट्टा, पैसे वाली फ़ैंटेसी और जुआ-ऐप इस तरह बनाए जाते हैं कि ज़्यादातर लोग हारें। भारत के ऑनलाइन गेमिंग अधिनियम, 2025 ने असली पैसे वाले ऑनलाइन गेम पर रोक लगाई है।", "किशोरों को कभी सट्टा नहीं लगाना चाहिए, और पैसे “जीतने” या “पाने” के लिए OTP या बैंक की जानकारी कभी नहीं देनी चाहिए। आप या आपका दोस्त मुश्किल में हो तो किसी भरोसेमंद बड़े को बताएँ।"]], "qz": [["₹999 instead of ₹1,000 is a trick because…", "₹1,000 की जगह ₹999 एक चाल है क्योंकि…", ["It feels much cheaper but is only ₹1 less", "It is a big discount", "It is free"], ["यह बहुत सस्ता लगता है पर सिर्फ़ ₹1 कम है", "यह बड़ी छूट है", "यह मुफ़्त है"], 0], ["An “Only 2 left!” banner mainly tries to…", "“सिर्फ़ 2 बचे हैं!” वाला बैनर मुख्य रूप से क्या करवाना चाहता है?", ["Make you hurry", "Help you compare", "Lower the price"], ["आपको जल्दबाज़ी में डालना", "तुलना में मदद करना", "दाम घटाना"], 0], ["An app says “Pay ₹100, win ₹10,000”. This is…", "एक ऐप कहता है “₹100 दें, ₹10,000 जीतें”। यह है…", ["Betting, which is banned for real-money games", "A savings account", "A school fee"], ["सट्टा, जिस पर असली पैसे वाले गेम में रोक है", "बचत खाता", "स्कूल की फ़ीस"], 0], ["Influencers who promote products are often…", "प्रोडक्ट का प्रचार करने वाले इन्फ़्लुएंसर अक्सर…", ["Paid to promote them", "Always neutral", "Never paid"], ["प्रचार के लिए पैसे पाते हैं", "हमेशा निष्पक्ष होते हैं", "कभी पैसे नहीं पाते"], 0], ["A game asks for your OTP to “claim” a prize. You should…", "एक गेम इनाम “पाने” के लिए आपका OTP माँगता है। आपको…", ["Never share it and tell an adult", "Share it quickly", "Post it online"], ["कभी नहीं बताना चाहिए और किसी बड़े को बताना चाहिए", "जल्दी से बता देना चाहिए", "ऑनलाइन पोस्ट कर देना चाहिए"], 0]]}, {"id": "b5", "l": 2, "n": ["Bank accounts and scam safety", "बैंक खाते और धोखाधड़ी से बचाव"], "sv": "card", "st": ["Zoya, 13, has a savings account opened with her mother. She has a passbook, a debit card and a UPI app linked to it. One day a caller says, “I am from your bank. Tell me the OTP so your card does not get blocked.” Zoya knows a bank never asks for an OTP, PIN or CVV. She hangs up and tells her mother, who calls the bank’s official number. They also report the call on the cyber helpline 1930.", "ज़ोया, 13 साल की, का बचत खाता माँ के साथ खुला है। उसके पास पासबुक, डेबिट कार्ड और उससे जुड़ा UPI ऐप है। एक दिन एक कॉल आती है: “मैं आपके बैंक से बोल रहा हूँ। OTP बताइए ताकि आपका कार्ड ब्लॉक न हो।” ज़ोया जानती है कि बैंक कभी OTP, पिन या CVV नहीं माँगता। वह फ़ोन काट देती है और माँ को बताती है, जो बैंक के आधिकारिक नंबर पर फ़ोन करती हैं। वे उस कॉल की शिकायत साइबर हेल्पलाइन 1930 पर भी करते हैं।"], "kn": [["A savings account keeps your money safe and pays interest. Children can have one with a parent or guardian; many banks let those aged 10 and above run it themselves with limits.", "A passbook or statement shows every deposit and withdrawal, so check it often. A debit card (with ATM PIN) and UPI let you spend the balance; a cheque is a written order for the bank to pay.", "Never share your OTP, PIN, CVV or password with anyone, even a caller who says they are from the bank.", "Cheated? Call 1930 at once and report on cybercrime.gov.in. Ask the bank to block the card or UPI."], ["बचत खाता आपके पैसे सुरक्षित रखता है और ब्याज देता है। बच्चे माता-पिता या अभिभावक के साथ खाता खोल सकते हैं; कई बैंक 10 साल और उससे ऊपर के बच्चों को सीमाओं के साथ ख़ुद चलाने देते हैं।", "पासबुक या स्टेटमेंट में हर जमा और निकासी दिखती है, इसलिए उसे अक्सर देखें। डेबिट कार्ड (ATM पिन के साथ) और UPI से आप बैलेंस ख़र्च कर सकते हैं; चेक बैंक को भुगतान करने का लिखित आदेश है।", "OTP, पिन, CVV या पासवर्ड किसी को न बताएँ, चाहे फ़ोन करने वाला ख़ुद को बैंक का कर्मचारी ही क्यों न कहे।", "धोखा हो जाए तो तुरंत 1930 पर फ़ोन करें और cybercrime.gov.in पर शिकायत करें। बैंक से कहकर कार्ड या UPI बंद करवाएँ।"]], "qz": [["A bank employee will never ask you for…", "बैंक का कर्मचारी आपसे कभी नहीं माँगेगा…", ["Your OTP or PIN", "Your name on a form", "A signature on a form"], ["आपका OTP या पिन", "फ़ॉर्म पर आपका नाम", "फ़ॉर्म पर हस्ताक्षर"], 0], ["A passbook or statement shows…", "पासबुक या स्टेटमेंट में दिखता है…", ["Every deposit and withdrawal", "Your school marks", "The weather"], ["हर जमा और निकासी", "आपके स्कूल के अंक", "मौसम"], 0], ["A caller asks for your OTP “to stop your card being blocked”. You should…", "फ़ोन करने वाला “कार्ड ब्लॉक होने से रोकने के लिए” OTP माँगता है। आपको…", ["Hang up and tell an adult", "Give the OTP", "Give the card number"], ["फ़ोन काटकर किसी बड़े को बताना चाहिए", "OTP दे देना चाहिए", "कार्ड नंबर दे देना चाहिए"], 0], ["India’s cyber-fraud helpline number is…", "भारत में साइबर-धोखाधड़ी की हेल्पलाइन का नंबर है…", ["1930", "100", "1098"], null, 0], ["A cheque is…", "चेक है…", ["A written order for the bank to pay", "A kind of coin", "An ATM card"], ["बैंक को भुगतान का लिखित आदेश", "एक तरह का सिक्का", "ATM कार्ड"], 0]]}, {"id": "b6", "l": 3, "n": ["Insurance and government schemes", "बीमा और सरकारी योजनाएँ"], "sv": "scale", "st": ["Aditya’s father pays a yearly premium of ₹8,000 for health insurance. One year Aditya’s grandmother needs a hospital operation costing ₹60,000, and the insurer pays the covered amount under the policy. Without insurance the family would have used up savings or borrowed. Aditya’s aunt also opens a Sukanya Samriddhi account for his cousin Meher, aged 6, and deposits money regularly. A Post Office recurring deposit is another safe, government-run way to save.", "आदित्य के पिता स्वास्थ्य बीमा का सालाना प्रीमियम ₹8,000 भरते हैं। एक साल आदित्य की दादी को अस्पताल में ₹60,000 के ऑपरेशन की ज़रूरत पड़ती है, और बीमा कंपनी पॉलिसी के तहत शामिल रक़म चुकाती है। बीमा न होता तो परिवार को बचत ख़र्च करनी पड़ती या उधार लेना पड़ता। आदित्य की बुआ अपनी 6 साल की भतीजी मेहर के लिए सुकन्या समृद्धि खाता भी खोलती हैं और नियमित रूप से पैसे जमा करती हैं। डाकघर की आवर्ती जमा (RD) बचत का एक और सुरक्षित, सरकारी तरीक़ा है।"], "kn": [["Insurance is a promise: you pay a small amount (premium) and the insurer pays for a big loss that is covered, such as hospital bills or an accident.", "Common types: health, life, motor and home. Before you buy, read what is covered, what is not and any waiting period.", "Ayushman Bharat PM-JAY gives eligible families health cover of up to ₹5 lakh a year for hospital care.", "Government savings options such as Post Office accounts, the Recurring Deposit (RD), PPF and Sukanya Samriddhi (for a girl child, opened before she turns 10) are set by the government. Their interest rates are reviewed every three months, so check the current rate."], ["बीमा एक वादा है: आप थोड़ी रक़म (प्रीमियम) देते हैं और बीमा कंपनी किसी बड़े नुक़सान, जैसे अस्पताल के बिल या दुर्घटना, का ख़र्च देती है, अगर वह पॉलिसी में शामिल हो।", "आम प्रकार: स्वास्थ्य, जीवन, वाहन और घर। ख़रीदने से पहले पढ़ें कि क्या शामिल है, क्या नहीं और प्रतीक्षा-अवधि क्या है।", "आयुष्मान भारत PM-JAY पात्र परिवारों को अस्पताल के इलाज के लिए साल में ₹5 लाख तक का स्वास्थ्य कवर देता है।", "डाकघर के खाते, आवर्ती जमा (RD), PPF और सुकन्या समृद्धि (बालिका के लिए, 10 साल की होने से पहले खोला जाता है) जैसे सरकारी बचत विकल्प सरकार तय करती है। इनकी ब्याज दरें हर तीन महीने पर देखी जाती हैं, इसलिए ताज़ा दर जाँच लें।"]], "qz": [["An insurance premium is…", "बीमा का प्रीमियम है…", ["The small payment you make to the insurer", "The money the insurer gives you every day", "A kind of loan"], ["बीमा कंपनी को दी जाने वाली छोटी रक़म", "जो रक़म बीमा कंपनी रोज़ देती है", "एक तरह का लोन"], 0], ["Health insurance mainly helps pay for…", "स्वास्थ्य बीमा मुख्य रूप से किसके ख़र्च में मदद करता है?", ["Hospital bills", "School uniforms", "Movie tickets"], ["अस्पताल के बिल", "स्कूल की वर्दी", "फ़िल्म के टिकट"], 0], ["Before buying a policy you should read…", "पॉलिसी ख़रीदने से पहले आपको पढ़ना चाहिए…", ["What is covered and what is not", "Only the colour of the brochure", "Nothing"], ["क्या शामिल है और क्या नहीं", "सिर्फ़ ब्रोशर का रंग", "कुछ नहीं"], 0], ["A Sukanya Samriddhi account is for…", "सुकन्या समृद्धि खाता किसके लिए है?", ["A girl child", "Any adult", "Pets"], ["बालिका के लिए", "किसी भी वयस्क के लिए", "पालतू जानवरों के लिए"], 0], ["Government small-saving interest rates are…", "सरकारी छोटी बचत की ब्याज दरें…", ["Set by the government and reviewed every three months", "Never changed", "Set by shopkeepers"], ["सरकार तय करती है और हर तीन महीने पर देखी जाती हैं", "कभी नहीं बदलतीं", "दुकानदार तय करते हैं"], 0]]}, {"id": "b7", "l": 3, "n": ["Documents and KYC", "दस्तावेज़ और KYC"], "sv": "card", "st": ["Hiral wants to open her first student bank account. The bank asks for proof of who she is and where she lives. This process is called KYC, “Know Your Customer”. She shows her Aadhaar, a 12-digit identity number, and her PAN card, which is used for tax records. A friend suggests posting a photo of her Aadhaar to a “scholarship” group. Hiral refuses. Her documents are keys to her money and identity, so she shares copies only with trusted organisations and for a stated reason.", "हीरल अपना पहला छात्र बैंक खाता खोलना चाहती है। बैंक उससे यह साबित करने को कहता है कि वह कौन है और कहाँ रहती है। इस प्रक्रिया को KYC यानी “अपने ग्राहक को जानें” कहते हैं। वह अपना आधार, यानी 12 अंकों की पहचान संख्या, और अपना PAN कार्ड दिखाती है, जो कर-रिकॉर्ड में काम आता है। एक दोस्त सुझाता है कि “छात्रवृत्ति” वाले ग्रुप में अपने आधार की फ़ोटो डाल दे। हीरल मना कर देती है। उसके दस्तावेज़ उसके पैसे और पहचान की चाबी हैं, इसलिए वह प्रतियाँ सिर्फ़ भरोसेमंद संस्थाओं को और बताए गए कारण के लिए ही देती है।"], "kn": [["KYC (Know Your Customer) means proving who you are before you open a bank account or use some financial services.", "Aadhaar is a 12-digit identity number issued by UIDAI. PAN is a 10-character number issued by the Income Tax Department for tax records and many financial tasks.", "Children can have Aadhaar, and a parent can apply for a PAN for a minor when it is needed.", "Never post photos of your documents online. Share copies only with trusted organisations, write the purpose on the copy, and never share OTPs."], ["KYC (अपने ग्राहक को जानें) का मतलब है बैंक खाता खोलने या कुछ वित्तीय सेवाएँ लेने से पहले अपनी पहचान साबित करना।", "आधार UIDAI द्वारा जारी 12 अंकों की पहचान संख्या है। PAN आयकर विभाग द्वारा जारी 10 अक्षर-अंकों का नंबर है, जो कर-रिकॉर्ड और कई वित्तीय कामों में काम आता है।", "बच्चों का भी आधार बन सकता है, और ज़रूरत पड़ने पर माता-पिता नाबालिग के लिए PAN के लिए आवेदन कर सकते हैं।", "अपने दस्तावेज़ों की फ़ोटो कभी ऑनलाइन पोस्ट न करें। प्रतियाँ सिर्फ़ भरोसेमंद संस्थाओं को दें, उस पर उद्देश्य लिख दें, और OTP कभी न बताएँ।"]], "qz": [["KYC stands for…", "KYC का पूरा रूप है…", ["Know Your Customer", "Keep Your Cash", "Kids Yearly Check"], ["नो योर कस्टमर (अपने ग्राहक को जानें)", "कीप योर कैश", "किड्स यियरली चेक"], 0], ["How many digits does an Aadhaar number have?", "आधार नंबर में कितने अंक होते हैं?", ["12", "4", "16"], null, 0], ["PAN is mainly used for…", "PAN मुख्य रूप से किसके काम आता है?", ["Tax records and many financial tasks", "Watching films", "Buying sweets"], ["कर-रिकॉर्ड और कई वित्तीय कामों में", "फ़िल्म देखने में", "मिठाई ख़रीदने में"], 0], ["A friend asks you to post your Aadhaar photo in a group. You should…", "एक दोस्त आपसे ग्रुप में आधार की फ़ोटो डालने को कहता है। आपको…", ["Refuse", "Post it", "Send it to strangers"], ["मना कर देना चाहिए", "पोस्ट कर देना चाहिए", "अजनबियों को भेज देना चाहिए"], 0], ["Who should get copies of your documents?", "आपके दस्तावेज़ों की प्रतियाँ किसे मिलनी चाहिए?", ["Only trusted organisations, for a stated reason", "Anyone who asks online", "Everyone in your class"], ["सिर्फ़ भरोसेमंद संस्थाओं को, बताए गए कारण के लिए", "ऑनलाइन माँगने वाले किसी को भी", "कक्षा में सबको"], 0]]}, {"id": "b8", "l": 3, "n": ["Goals, giving and where savings grow", "लक्ष्य, दान और बचत कहाँ बढ़ती है"], "sv": "line", "st": ["Ishaan sets three goals. Short: ₹1,200 headphones in 6 months, so ₹200 a month. Medium: a ₹30,000 laptop in 3 years, so ₹10,000 a year. Long: college fees in 8 years. He also gives ₹100 a month to a school scholarship fund, because he wants to help others too. He learns that savings can sit in a savings account, in a fixed deposit (FD) for steady interest, or, for far goals and with an adult’s guidance, in mutual funds or shares that go up and down. For short goals he picks safe options. For long goals he can accept some ups and downs.", "ईशान तीन लक्ष्य बनाता है। छोटा: 6 महीने में ₹1,200 के हेडफ़ोन, यानी ₹200 महीना। मध्यम: 3 साल में ₹30,000 का लैपटॉप, यानी ₹10,000 साल। लंबा: 8 साल में कॉलेज की फ़ीस। वह स्कूल की छात्रवृत्ति निधि में हर महीने ₹100 भी देता है, क्योंकि वह दूसरों की मदद करना चाहता है। वह सीखता है कि बचत बचत खाते में, स्थिर ब्याज के लिए फ़िक्स्ड डिपॉज़िट (FD) में, या दूर के लक्ष्यों के लिए और बड़े की सलाह से म्यूचुअल फ़ंड या शेयरों में रखी जा सकती है, जो ऊपर-नीचे होते रहते हैं। छोटे लक्ष्यों के लिए वह सुरक्षित विकल्प चुनता है। लंबे लक्ष्यों के लिए वह थोड़ा उतार-चढ़ाव सह सकता है।"], "kn": [["Write goals with an amount and a date. Divide the amount by the months to find what to save each month.", "Short goals (under 1 year) need safe places such as a savings account. Medium goals (1 to 5 years) suit an FD or RD. Long goals (5+ years) can include growth options like equity mutual funds, with an adult’s guidance and only for money you will not need soon.", "Giving is also part of good money habits. Even a small regular donation to a trusted cause counts.", "Check that a scheme is registered or regulated (RBI for banks, SEBI for investments) before putting money in."], ["लक्ष्य रक़म और तारीख़ के साथ लिखें। रक़म को महीनों से भाग देकर हर महीने की बचत निकालें।", "छोटे लक्ष्य (1 साल से कम) के लिए बचत खाते जैसी सुरक्षित जगह चाहिए। मध्यम लक्ष्य (1 से 5 साल) के लिए FD या RD ठीक रहती है। लंबे लक्ष्य (5+ साल) में इक्विटी म्यूचुअल फ़ंड जैसे बढ़त वाले विकल्प हो सकते हैं, बड़े की सलाह से और सिर्फ़ उस पैसे के लिए जो जल्दी नहीं चाहिए।", "देना भी पैसे की अच्छी आदतों का हिस्सा है। किसी भरोसेमंद संस्था को छोटा नियमित दान भी मायने रखता है।", "पैसा लगाने से पहले जाँच लें कि योजना पंजीकृत या विनियमित है (बैंकों के लिए RBI, निवेश के लिए SEBI)।"]], "qz": [["To save ₹1,200 in 6 months, you save each month…", "6 महीने में ₹1,200 बचाने के लिए हर महीने बचाएँ…", ["₹100", "₹200", "₹600", "₹1,200"], null, 1], ["To save ₹30,000 in 3 years, you save each year…", "3 साल में ₹30,000 बचाने के लिए हर साल बचाएँ…", ["₹3,000", "₹10,000", "₹15,000", "₹90,000"], null, 1], ["Which place is best for a goal only 6 months away?", "सिर्फ़ 6 महीने दूर के लक्ष्य के लिए सबसे अच्छी जगह कौन-सी है?", ["A safe savings account", "A risky share tip", "A game"], ["सुरक्षित बचत खाता", "शेयर की जोखिम भरी टिप", "एक गेम"], 0], ["A good goal has…", "अच्छे लक्ष्य में होती है…", ["An amount and a date", "Only a wish", "No plan"], ["रक़म और तारीख़", "सिर्फ़ एक इच्छा", "कोई योजना नहीं"], 0], ["Before putting money in a scheme, check that it is…", "किसी योजना में पैसा लगाने से पहले जाँचें कि वह…", ["Registered or regulated", "Popular in chat groups", "Promising “guaranteed” returns"], ["पंजीकृत या विनियमित है", "चैट ग्रुपों में लोकप्रिय है", "“गारंटीड” रिटर्न का वादा करती है"], 0]]}];
